import json
from pathlib import Path
R=lambda x:{'Ref':x}
A=lambda x,y:{'Fn::GetAtt':[x,y]}
S=lambda x:{'Fn::Sub':x}
resources={}
def resource(name,kind,props,**extra):resources[name]={'Type':kind,'Properties':props,**extra}
resource('SiteBucket','AWS::S3::Bucket',{'PublicAccessBlockConfiguration':{k:True for k in ['BlockPublicAcls','IgnorePublicAcls','BlockPublicPolicy','RestrictPublicBuckets']},'VersioningConfiguration':{'Status':'Enabled'}},DeletionPolicy='Retain',UpdateReplacePolicy='Retain')
resource('TransferBucket','AWS::S3::Bucket',{'PublicAccessBlockConfiguration':{k:True for k in ['BlockPublicAcls','IgnorePublicAcls','BlockPublicPolicy','RestrictPublicBuckets']},'BucketEncryption':{'ServerSideEncryptionConfiguration':[{'ServerSideEncryptionByDefault':{'SSEAlgorithm':'AES256'}}]},'LifecycleConfiguration':{'Rules':[{'Id':'TemporaryAudio','Status':'Enabled','ExpirationInDays':1,'Prefix':'uploads/'}]},'CorsConfiguration':{'CorsRules':[{'AllowedOrigins':['https://gettelecode.com','https://www.gettelecode.com'],'AllowedMethods':['GET','POST'],'AllowedHeaders':['*'],'MaxAge':300}]}},DeletionPolicy='Retain')
resource('TransferBucketPolicy','AWS::S3::BucketPolicy',{'Bucket':R('TransferBucket'),'PolicyDocument':{'Version':'2012-10-17','Statement':[{'Effect':'Deny','Principal':'*','Action':'s3:*','Resource':[A('TransferBucket','Arn'),S('${TransferBucket.Arn}/*')],'Condition':{'Bool':{'aws:SecureTransport':'false'}}}]}})
resource('Table','AWS::DynamoDB::Table',{'BillingMode':'PAY_PER_REQUEST','AttributeDefinitions':[{'AttributeName':k,'AttributeType':'S'} for k in ['pk','sk']],'KeySchema':[{'AttributeName':'pk','KeyType':'HASH'},{'AttributeName':'sk','KeyType':'RANGE'}],'TimeToLiveSpecification':{'AttributeName':'expiresAt','Enabled':True},'PointInTimeRecoverySpecification':{'PointInTimeRecoveryEnabled':True}},DeletionPolicy='Retain')
resource('UserPool','AWS::Cognito::UserPool',{'UserPoolName':'gettelecode-openDAW','UsernameAttributes':['email'],'AutoVerifiedAttributes':['email'],'Policies':{'PasswordPolicy':{'MinimumLength':12,'RequireUppercase':True,'RequireLowercase':True,'RequireNumbers':True,'RequireSymbols':True}},'AccountRecoverySetting':{'RecoveryMechanisms':[{'Name':'verified_email','Priority':1}]}})
resource('UserClient','AWS::Cognito::UserPoolClient',{'UserPoolId':R('UserPool'),'ClientName':'openDAW-web','GenerateSecret':False,'AllowedOAuthFlowsUserPoolClient':True,'AllowedOAuthFlows':['code'],'AllowedOAuthScopes':['openid','email'],'SupportedIdentityProviders':['COGNITO'],'CallbackURLs':['https://gettelecode.com/account.html','https://gettelecode.com/remote-signin.html'],'LogoutURLs':['https://gettelecode.com/account.html'],'PreventUserExistenceErrors':'ENABLED','EnableTokenRevocation':True,'IdTokenValidity':1,'TokenValidityUnits':{'IdToken':'hours'}})
resource('UserDomain','AWS::Cognito::UserPoolDomain',{'Domain':S('opendaw-${AWS::AccountId}'),'UserPoolId':R('UserPool')})
resource('HttpApi','AWS::ApiGatewayV2::Api',{'Name':'openDAW MCP','ProtocolType':'HTTP'})
resource('WsApi','AWS::ApiGatewayV2::Api',{'Name':'openDAW browser bridge','ProtocolType':'WEBSOCKET','RouteSelectionExpression':'$request.body.type'})
resource('Role','AWS::IAM::Role',{'AssumeRolePolicyDocument':{'Version':'2012-10-17','Statement':[{'Effect':'Allow','Principal':{'Service':'lambda.amazonaws.com'},'Action':'sts:AssumeRole'}]},'ManagedPolicyArns':['arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole'],'Policies':[{'PolicyName':'BridgeStore','PolicyDocument':{'Version':'2012-10-17','Statement':[{'Effect':'Allow','Action':['s3:PutObject','s3:GetObject','s3:DeleteObject'],'Resource':S('${TransferBucket.Arn}/uploads/*')},{'Effect':'Allow','Action':['dynamodb:GetItem','dynamodb:PutItem','dynamodb:DeleteItem','dynamodb:UpdateItem','dynamodb:Query','dynamodb:TransactWriteItems'],'Resource':A('Table','Arn')},{'Effect':'Allow','Action':'execute-api:ManageConnections','Resource':S('arn:${AWS::Partition}:execute-api:${AWS::Region}:${AWS::AccountId}:${WsApi}/prod/POST/@connections/*')},{'Effect':'Allow','Action':'execute-api:ManageConnections','Resource':S('arn:${AWS::Partition}:execute-api:${AWS::Region}:${AWS::AccountId}:${WsApi}/prod/DELETE/@connections/*')}]}}]})
resource('Function','AWS::Lambda::Function',{'Runtime':'nodejs24.x','Handler':'handler.handler','Architectures':['arm64'],'MemorySize':512,'Timeout':20,'Role':A('Role','Arn'),'Code':{'S3Bucket':R('ArtifactBucket'),'S3Key':R('ArtifactKey')},'Environment':{'Variables':{'TRANSFER_BUCKET':R('TransferBucket'),'TABLE_NAME':R('Table'),'USER_POOL_ID':R('UserPool'),'CLIENT_ID':R('UserClient'),'WS_MANAGEMENT_URL':S('https://${WsApi}.execute-api.${AWS::Region}.amazonaws.com/prod')}}})
resource('Logs','AWS::Logs::LogGroup',{'LogGroupName':S('/aws/lambda/${Function}'),'RetentionInDays':14})
for kind in ['Http','Ws']:
    resource(kind+'Integration','AWS::ApiGatewayV2::Integration',{'ApiId':R(kind+'Api'),'IntegrationType':'AWS_PROXY','IntegrationUri':A('Function','Arn') if kind=='Http' else S('arn:${AWS::Partition}:apigateway:${AWS::Region}:lambda:path/2015-03-31/functions/${Function.Arn}/invocations'),**({'PayloadFormatVersion':'2.0'} if kind=='Http' else {'IntegrationMethod':'POST'})})
    resource(kind+'Permission','AWS::Lambda::Permission',{'FunctionName':R('Function'),'Action':'lambda:InvokeFunction','Principal':'apigateway.amazonaws.com','SourceArn':S('arn:${AWS::Partition}:execute-api:${AWS::Region}:${AWS::AccountId}:${'+kind+'Api}/*')})
resource('HttpRoute','AWS::ApiGatewayV2::Route',{'ApiId':R('HttpApi'),'RouteKey':'$default','Target':S('integrations/${HttpIntegration}')})
resource('HttpStage','AWS::ApiGatewayV2::Stage',{'ApiId':R('HttpApi'),'StageName':'$default','AutoDeploy':True,'DefaultRouteSettings':{'ThrottlingBurstLimit':20,'ThrottlingRateLimit':10}})
for name,route in [('Connect','$connect'),('Disconnect','$disconnect'),('Default','$default')]:
    resource('Ws'+name,'AWS::ApiGatewayV2::Route',{'ApiId':R('WsApi'),'RouteKey':route,'Target':S('integrations/${WsIntegration}')})
resource('WsStage','AWS::ApiGatewayV2::Stage',{'ApiId':R('WsApi'),'StageName':'prod','AutoDeploy':True,'DefaultRouteSettings':{'ThrottlingBurstLimit':20,'ThrottlingRateLimit':10}})
resource('OriginAccess','AWS::CloudFront::OriginAccessControl',{'OriginAccessControlConfig':{'Name':'openDAW-gettelecode','OriginAccessControlOriginType':'s3','SigningBehavior':'always','SigningProtocol':'sigv4'}})
resource('BucketPolicy','AWS::S3::BucketPolicy',{'Bucket':R('SiteBucket'),'PolicyDocument':{'Version':'2012-10-17','Statement':[{'Effect':'Allow','Principal':{'Service':'cloudfront.amazonaws.com'},'Action':'s3:GetObject','Resource':S('${SiteBucket.Arn}/*'),'Condition':{'StringEquals':{'AWS:SourceArn':'arn:aws:cloudfront::172376196185:distribution/E3CT71G02GLRD5'}}}]}})
outputs={k:{'Value':v} for k,v in {'TransferBucket':R('TransferBucket'),'SiteBucket':R('SiteBucket'),'HttpApi':R('HttpApi'),'WsApi':R('WsApi'),'UserPool':R('UserPool'),'ClientId':R('UserClient'),'AuthDomain':S('https://${UserDomain}.auth.${AWS::Region}.amazoncognito.com'),'Function':R('Function'),'Table':R('Table'),'OriginAccess':R('OriginAccess')}.items()}
Path(__file__).with_name('template.json').write_text(json.dumps({'AWSTemplateFormatVersion':'2010-09-09','Description':'openDAW multi-user remote control on gettelecode.com','Parameters':{'ArtifactBucket':{'Type':'String'},'ArtifactKey':{'Type':'String'}},'Resources':resources,'Outputs':outputs},indent=2)+'\n')
